//  6. Текст + « (בדיקת QA)» → «אישור ופרסום» → «לא תואמות לטקסט: 1», в קטע «לא תואמת את הטקסט הנוכחי של הקטע או את הנוסח — אינה מוצעת…».
//  7. Пользователь: новый текст сразу («(בדיקת QA)»), «אין הקראה לקטע הזה», «השמע» disabled (F-92 AC2, F-102 AC4).
//  8. «הסרת ההקראה» → «להסיר את ההקראה?» → «הסרת ההקראה» → «ההקראה הוסרה.»; «מחיקת הקטע» → окно → «הקטע מסומן למחיקה…» →
//     «שם המאשר» → «אישור ופרסום השינוי»; итог как в начале (25.10: «0 מתוך 1 קטעים מאושרים», у пользователя «1 מתוך 1»).
// Шаг 8 снимает запись ДО удаления קטע — это проверка «הסרת ההקראה» отдельно (F-92). С 26.10 (#544d9c исправлен) удалять קטע можно и
// вместе с записью — это проверяет q-18 (Q-18a/b); уборка cleanupQaSection запись заранее не снимает.
// @admin @data: вход клиента — человек (QA_ADMIN_MANUAL=1). НЕЛЬЗЯ: «אישור כל התפילה», «שחרית · נוסח ספרד», קטעים с чужой озвучкой.
// Уборка — after(): выполняется и при падении. Необратимо: строки «היסטוריית אישורים». Подсветки слов нет и не проверяется.
// Пауза 5 с в шаге 5 — не ожидание интерфейса, а нужная длительность игры для проверки «продолжает с места» (как rc-02).
import { driver, expect } from '@wdio/globals';
import { byText, byTextContains, scrollToText } from '../../helpers/ui.ts';
import { openSection, setBody, readBody, qaMarker } from '../_lib/admin.ts';
import { approvedCount, ADM_DELETE, ADM_DELETE_TITLE } from '../_lib/app-2110.ts';
import { nodes, counterNM } from '../_lib/readiness-1910.ts';
import { playerButton, recordingLine, skipWith } from '../_lib/app-0710.ts';
import { removeRecordingWithDialog } from '../_lib/app-1310.ts';
import {
  REC_APPROVER, REC_FILE_SECONDS, REC_UPLOADED_BY, REC_NOT_MATCHING_FULL, REC_NOT_OFFERED, USER_REC_LINE, ADM_MARKED_DELETE,
  qaRecTitle, arvitAshkK3Text, requireClientLogin, openRecAdminPrayer, addSectionHere, hasSectionRow, uploadQaRecording,
  approveQaRecording, publishWithApprover, cleanupQaSection, recSummaryNow, openUserRecPage, toPlayer, expectNoRecordingForUser,
  tapPlayer, waitPlaybackEnd, saveShot, dialogDeleteButton, approveStructuralChange,
} from '../_lib/app-2510.ts';

const TITLE = qaRecTitle('הקראה');
const EDIT_SUFFIX = ' (בדיקת QA)';

describe('25.10 — озвучка на своём QA קטע «ברכת הלבנה · אשכנז» (F-91 / F-92)', () => {
  let started = false;
  let base: [number, number] = [0, 0];
  let userTotal0 = 0;

  after(async function () {
    this.timeout(900000);
    if (!started) return;
    try {
      const after = await cleanupQaSection(TITLE, REC_APPROVER, qaMarker('Q17-cleanup'));
      if (after[0] !== base[0] || after[1] !== base[1]) console.warn(`[Q-17] после уборки ${after.join('/')} ≠ исходно ${base.join('/')} — проверить вручную`);
    } catch (e) {
      console.warn(`[Q-17] УБОРКА НЕ ЗАВЕРШЕНА: удалить вручную «${TITLE}» (сначала «הסרת ההקראה», потом «מחיקת הקטע» → «אישור ופרסום השינוי»)`, e);
    }
  });

  it('Q-17 свой QA קטע → MP3 «ממתינה» (пользователь: אין הקראה, השמע disabled) → утверждение (הקראה: בודק QA · אושרה…, השמע/השהה, пауза→продолжение с места, стоп в конце ≈23 с) → правка текста → «לא תואמת» (пользователь: новый текст, אין הקראה, disabled) → «הסרת ההקראה» → удаление קטע #F-91 #F-92 #6a86f7eda7b2 #6a86f7ed9d38 F-91 AC3 AC4 F-92 AC1 AC2 AC4 F-102 AC4 @admin @data @manual-check', async function () {
    this.timeout(3600000);
    await requireClientLogin(this);
    const body = arvitAshkK3Text();

    // 0. Исходно (25.10: «0 מתוך 1 קטעים מאושרים», у пользователя «1 מתוך 1»); своего QA קטע нет.
    await openRecAdminPrayer('исходно');
    base = await approvedCount();
    if (await hasSectionRow(TITLE)) throw new Error(`«${TITLE}» уже есть (остаток прошлого прогона) — убрать вручную перед тестом`);
    [, userTotal0] = await openUserRecPage(1);

    // 1. «+ הוספת קטע כאן» → заголовок, текст «המעריב ערבים», «שם המאשר» → «אישור ופרסום» → окно → «אישור».
    await openRecAdminPrayer('шаг 1');
    started = true;
    await addSectionHere(TITLE, body, REC_APPROVER, qaMarker('Q17-add'));
    await openRecAdminPrayer('шаг 1: проверка');
    expect(await hasSectionRow(TITLE)).toBe(true);

    // 2. «מי הקליט» = «בודק QA» → «העלאת קובץ MP3» → «arvit-ashk-k3 2» → «הוקלט על ידי … · הועלה על ידי מנהל תוכן», «ממתינה לאישור…».
    await openSection(TITLE);
    if (!(await uploadQaRecording(REC_APPROVER))) skipWith(this, 'на телефоне нет файла «arvit-ashk-k3 2» в «Файлы → Недавние» (копия .qa/research/rec-pages/arvit-ashk-k3.mp3)');
    await expect(byTextContains(REC_UPLOADED_BY(REC_APPROVER))).toBeExisting({ wait: 15000 });
    await saveShot('Q-17-2-pending.png');

    // 3. Пользователь: последняя страница = новый קטע («2 מתוך 2» при исходных 1) — записи нет, «השמע» неактивна.
    const page = userTotal0 + 1;
    const [n3, m3] = await openUserRecPage(page);
    expect([n3, m3]).toEqual([page, page]);
    await expectNoRecordingForUser();

    // 4. Админка: «אישור ההקראה ופרסומה» → «ההקראה אושרה ומוצעת עכשיו להשמעה בקטע הזה.», «אושרה על ידי מנהל תוכן, … — מוצעת להשמעה».
    await openRecAdminPrayer('шаг 4');
    await openSection(TITLE);
    await approveQaRecording();
    await saveShot('Q-17-4-approved.png');

    // 5. Пользователь: строка «הקראה: בודק QA · אושרה על ידי מנהל תוכן», «השמע» активна, без автозапуска.
    await openUserRecPage(page);
    await toPlayer();
    await expect(recordingLine()).toBeExisting({ wait: 15000 });
    await expect(byTextContains(USER_REC_LINE(REC_APPROVER))).toBeExisting();
    await expect(await playerButton('השמע')).toBeEnabled();
    //    «השמע» → «השהה» → «השמע» (F-91 AC3).
    await tapPlayer('השמע');
    await tapPlayer('השהה');
    //    Полное проигрывание без паузы: кнопка сама вернулась в «השמע» ≈ через длину файла (23.4 с), страница та же.
    await tapPlayer('השמע');
    const full = await waitPlaybackEnd();
    expect(full).toBeGreaterThan(REC_FILE_SECONDS - 6);
    expect(full).toBeLessThan(REC_FILE_SECONDS + 20);
    expect(await counterNM()).toEqual([page, page]);
    //    ~5 с игры → пауза → продолжение: остаток короче полной записи (продолжает с места, а не сначала).
    await tapPlayer('השמע');
    await driver.pause(5000);
    await tapPlayer('השהה');
    await tapPlayer('השמע');
    const rest = await waitPlaybackEnd();
    expect(rest).toBeLessThan(full - 3);
    expect(await counterNM()).toEqual([page, page]);

    // 6. Админка: текст + « (בדיקת QA)» → «אישור ופרסום» → сводка «לא תואמות לטקסט: 1», в קטע «לא תואמת … — אינה מוצעת».
    await openRecAdminPrayer('шаг 6');
    await openSection(TITLE);
    await setBody(body + EDIT_SUFFIX);
    await publishWithApprover(REC_APPROVER, qaMarker('Q17-edit'));
    expect((await recSummaryNow()).notMatching).toBe(1);
    await openSection(TITLE);
    expect(await readBody()).toContain(EDIT_SUFFIX.trim());
    await expect(await scrollToText(REC_NOT_MATCHING_FULL)).toBeExisting();
    await expect(byTextContains(REC_NOT_OFFERED)).toBeExisting();
    await saveShot('Q-17-6-not-matching.png');

    // 7. Пользователь: новый текст сразу, записи нет, «השמע» неактивна.
    await openUserRecPage(page);
    expect((await nodes()).some((n) => n.label.includes(EDIT_SUFFIX.trim()))).toBe(true);
    await expectNoRecordingForUser();

    // 8. Уборка с проверками: «הסרת ההקראה» → «ההקראה הוסרה.»; «מחיקת הקטע» → «הקטע מסומן למחיקה…» → «אישור ופרסום השינוי».
    await openRecAdminPrayer('шаг 8');
    await openSection(TITLE);
    expect(await removeRecordingWithDialog()).toBe(true);
    await (await scrollToText(ADM_DELETE)).click();
    await (await byText(ADM_DELETE_TITLE(TITLE))).waitForExist({ timeout: 10000 });
    await (await dialogDeleteButton()).click();
    await expect(byTextContains(ADM_MARKED_DELETE)).toBeExisting({ wait: 20000 });
    await approveStructuralChange(REC_APPROVER, qaMarker('Q17-del'));
    await openRecAdminPrayer('шаг 8: итог');
    expect(await hasSectionRow(TITLE)).toBe(false);
    expect(await approvedCount()).toEqual(base);                     // 25.10: «0 מתוך 1 קטעים מאושרים»
    const [, userTotal1] = await openUserRecPage(1);
    expect(userTotal1).toBe(userTotal0);                             // 25.10: «1 מתוך 1»
    started = false;                                                 // уборка в after() не нужна
  });
});

